5	/// AD-13 — the never-throws wrapper RF08 and RF10 both need for a side
6	/// effect that must never block or crash its caller, even on failure.
7	///
8	/// spec-6-4 (RF10) is this helper's first real consumer, per the
9	/// architecture spine; spec-6-5 reuses it fire-and-forget (unawaited).
10	typedef IsolatedSideEffect<T> = Future<Either<Failure, T>> Function(
11	  Future<T> Function() action,
12	);
13	
14	/// Runs [action], mapping any thrown exception (sync or async) to
15	/// [Failure.malformedResponse] rather than letting it escape — mirrors
16	/// `EntriesRepositoryImpl`'s own existing catch-to-`malformedResponse`
17	/// convention (`entries_repository_impl.dart`'s Hive-write guards). A
18	/// caller that awaits this never needs its own try/catch; a caller that
19	/// fires it unawaited (spec-6-5) can never crash the isolate it runs in
20	/// either way.
21	Future<Either<Failure, T>> isolatedSideEffect<T>(
22	  Future<T> Function() action,
23	) async {
24	  try {
25	    return right(await action());
26	  } catch (error) {
27	    return left(Failure.malformedResponse(message: error.toString()));
28	  }
29	}
